set -euo pipefail
for P in jq pandoc; do
  echo ===$P_POLICY===
  apt-cache policy "$P" || true
  echo ===$P_SHOW===
  apt-cache show "$P" 2>/dev/null | grep -E '^(Package|Version|SHA256|Description):' | head -n 20 || true
done
echo ===JQ_HELP===
(jq --help || true) | head -n 100
echo ===PANDOC_HELP===
(pandoc --help || true) | head -n 120
